    "Bạn có chắc chắn gỡ bài hát này khỏi trang của mình theo yêu cầu của đối tác không?": "คุณแน่ใจหรือไม่ที่จะลบเพลงนี้ออกจากเพจของคุณตามคำขอของพาร์ทเนอร์?",
