    "Bạn có chắc muốn làm mới toàn bộ Secret Link? Các Secret Link cũ sẽ không còn hoạt động, tự động chuyển về đường dẫn gốc yêu cầu mật khẩu.": "คุณแน่ใจหรือไม่ที่จะรีเฟรช Secret Link ทั้งหมด? ลิงก์เดิมจะไม่สามารถใช้งานได้และจะกลับไปเป็นลิงก์ที่ต้องใช้รหัสผ่านโดยอัตโนมัติ",
