    "Hệ thống sẽ giữ tạm thời các mục trên tại đây tối đa 30 ngày. Quá thời gian này, các mục sẽ bị dọn dẹp và xóa vĩnh viễn không thể khôi phục.": "ระบบจะเก็บรายการข้างต้นไว้ที่นี่ชั่วคราวสูงสุด 30 วัน หลังจากเวลานี้ รายการจะถูกล้างและลบถาวร ไม่สามารถกู้คืนได้",
    "Hệ thống sẽ tự động sử dụng AI (Gemini) để dịch tất cả thông tin hồ sơ, tiêu đề, mô tả, các đề mô (tên, lyrics, tác giả, ca sĩ) và danh sách phát sang 5 ngôn ngữ khác (Anh, Hàn, Nhật, Thái, Trung). Quá trình này có thể mất khoảng 5-10 giây. Bạn có muốn tiếp tục?": "ระบบจะใช้ AI (Gemini) แปลข้อมูลโปรไฟล์ หัวข้อ คำอธิบาย เดโม (ชื่อ, เนื้อเพลง, ผู้แต่ง, นักร้อง) และเพลย์ลิสต์เป็น 5 ภาษาอื่นโดยอัตโนมัติ (อังกฤษ, เกาหลี, ญี่ปุ่น, ไทย, จีน) กระบวนการนี้อาจใช้เวลาประมาณ 5-10 วินาที คุณต้องการดำเนินการต่อหรือไม่?",
